/// The guard that a checked-in `*.reflection.dart` still describes its root.
///
/// Reflection metadata is generated by `./reflection_generation.sh` and
/// **committed**, so the file in git is the one the suite loads. Nothing in
/// Dart couples the two: adding a reflected class or an entity column and not
/// regenerating leaves a tree that compiles, analyzes clean, and fails only
/// later — at the mirror lookup, from a test that names neither the class nor
/// the file, with "Reflection has not been initialized" or a null member.
///
/// ## Why a name check rather than a regeneration
///
/// The exact check would be to regenerate and compare, and that is what
/// `tool/check_reflection_current.sh` does. It cannot live here: a run takes
/// two to four minutes against the whole package graph, which is longer than
/// this suite's entire wall time and would be paid by every developer on every
/// unrelated change.
///
/// So this test buys most of that certainty for milliseconds. It cannot prove
/// the generated file is *current* — only that it is not missing the things
/// most recently added — but the failure it catches is the one that actually
/// happens: someone edits a fixture and forgets the slow script. Both
/// names checked are the names a person adds by hand.
///
/// ## Why names are matched as raw strings
///
/// The generator emits declaration names as raw single-quoted literals
/// (`r'FixtureExportRecord'`) and member names as bare identifiers, so a
/// present class is `r'<Name>'` somewhere in the output and a present column is
/// its own identifier. Matching the quoted form for classes is deliberate: a
/// bare `FixtureExportRecord` also occurs inside type references the generator
/// emits for *other* classes that mention it, so an unquoted match would report
/// a class as captured when only a reference to it survived.
///
/// ## What this does not check
///
/// Index currency. The generated file numbers every captured member in one
/// dense global sequence, so adding a single public member to `lib/` shifts
/// every index after it and rewrites thousands of lines — see
/// `doc/reflection_generation.md`. Those indices are exactly what a name check
/// cannot see, and exactly what regenerating settles. When a diff looks
/// alarming, that document says which shape is expected.
library;

import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:test/test.dart';

/// A reflection root paired with the generated file it produces.
typedef _ReflectionRoot = ({
  /// The root's own path, for the failure message.
  String rootPath,

  /// The generated output the root produces.
  String generatedPath,

  /// The hand-written sources whose declarations must appear in the output.
  List<String> sources,

  /// Directories walked for the same purpose, when the sources are too many to
  /// name and adding one is not a wiring decision.
  ///
  /// The distinction from [sources] is which mistake the list is protecting
  /// against. An *example* entity file has to be wired into the example root by
  /// hand, so a glob there would hide a file that was never wired in at all —
  /// the list is the wiring. `lib/` needs no wiring: the fixture root imports
  /// the package barrel, so every reflected class the package exports is
  /// already in the graph, and naming them one by one would be a second
  /// inventory of `lib/` that goes stale on its own.
  List<String> sourceDirectories,
});

/// The two roots configured in `build.yaml`, each with the sources a person
/// edits by hand when adding something the generator must capture.
///
/// The example root's entity files are listed rather than globbed because the
/// root captures what its import graph reaches, and that graph is the four
/// files named here — a fifth example entity file is exactly the case this
/// list must be extended for, and a glob would hide that it was never wired
/// into `example_reflection.dart` at all.
const List<_ReflectionRoot> _roots = [
  (
    rootPath: 'test/fixtures/reflection_fixture.dart',
    generatedPath: 'test/fixtures/reflection_fixture.reflection.dart',
    sources: ['test/fixtures/reflection_fixture.dart'],
    // `lib/` as well as the fixture, and this is the half that matters most.
    // The fixture's own classes are read by tests that would fail loudly
    // without them; the package's are read by *discovery* — the walks over
    // `tomReflector.annotatedClasses` that find services, components,
    // datasource drivers and scheduled jobs — and a class missing from those
    // is a start-up failure at a deployment and silence in a suite.
    sourceDirectories: ['lib/src/tomserver'],
  ),
  (
    rootPath: 'example/example_reflection.dart',
    generatedPath: 'example/example_reflection.reflection.dart',
    sources: [
      'example/endpoints/endpoints_entities.dart',
      'example/export/export_entities.dart',
      'example/object_persistence/object_persistence_entities.dart',
      'example/scheduling/cluster/cluster_reflection.dart',
    ],
    sourceDirectories: [],
  ),
];

/// Every `.dart` file [root] draws declarations from, generated files excluded.
///
/// An artifact restates the annotations it was built from, so reading one would
/// make the comparison below run the generated file against itself.
Map<String, String> _sourcesOf(_ReflectionRoot root) => {
  for (final path in root.sources) path: _read(path),
  for (final directory in root.sourceDirectories)
    for (final entry in Directory(directory).listSync(recursive: true))
      if (entry is File &&
          entry.path.endsWith('.dart') &&
          !entry.path.endsWith('.reflection.dart'))
        entry.path: entry.readAsStringSync(),
};

/// The classes in [source] carrying a `@tomReflector` annotation.
///
/// Attribution is line-based rather than a regex over the gap between the
/// annotation and the declaration, because that gap holds the class's other
/// annotations (`@tomService`, `@TomDbTable(...)` over several lines) and any
/// character budget wide enough for those is wide enough to reach past the
/// class into the *next* one. It did: a bounded-gap version of this claimed
/// `FixtureTaskRepository`, whose doc comment says in as many words that it
/// carries no `@tomReflector`, and reported the generated file stale for a
/// class that was never meant to be in it.
///
/// So an annotation is attributed only when nothing but further annotations,
/// comments and blank lines separate it from the declaration. Anything else
/// ends the run.
Set<String> _reflectorClasses(String source) {
  final found = <String>{};
  var pendingReflector = false;
  var parenDepth = 0;

  for (final raw in const LineSplitter().convert(source)) {
    final line = raw.trim();

    // Inside a multi-line annotation such as @TomDbTable( … ): still part of
    // the annotation run, so the pending reflector survives it.
    if (parenDepth > 0) {
      parenDepth += _netParens(line);
      continue;
    }
    if (line.isEmpty || line.startsWith('//')) continue;

    final declaration = RegExp(
      r'^(?:abstract\s+)?(?:base\s+|final\s+|interface\s+|sealed\s+)?class\s+(\w+)',
    ).firstMatch(line);
    if (declaration != null) {
      if (pendingReflector) found.add(declaration.group(1)!);
      pendingReflector = false;
      continue;
    }

    if (line.startsWith('@')) {
      if (line == '@tomReflector') pendingReflector = true;
      parenDepth += _netParens(line);
      continue;
    }

    // Anything else — a field, a method, a closing brace — ends the run, so an
    // annotation cannot reach across a class body into the next declaration.
    pendingReflector = false;
  }
  return found;
}

/// `(` minus `)` in [line], ignoring those inside string literals.
///
/// Only accurate enough to track whether a multi-line annotation is still open;
/// annotation arguments here are identifiers, strings and lists, never nested
/// parenthesised expressions.
int _netParens(String line) {
  final bare = line.replaceAll(RegExp(r"'[^']*'"), '');
  return '('.allMatches(bare).length - ')'.allMatches(bare).length;
}

/// The type names listed in `example_reflection.dart`'s `exampleReflectedTypes`.
///
/// That list is the example root's own statement of what it exists to capture,
/// which makes it the right thing to hold the generated file against.
Set<String> _declaredExampleTypes(String source) {
  final list = RegExp(
    r'exampleReflectedTypes\s*=\s*<Type>\[([\s\S]*?)\];',
  ).firstMatch(source);
  if (list == null) return const {};
  return RegExp(
    r'^\s*(\w+),',
    multiLine: true,
  ).allMatches(list.group(1)!).map((match) => match.group(1)!).toSet();
}

/// The field names in [source] annotated with `@TomDbColumn`.
///
/// A persisted column is the member most often added on its own, and the one
/// whose absence from the generated file is hardest to attribute: the entity
/// still reflects, so the failure is a null column rather than a missing class.
///
/// The class annotations in [source] that bind to something other than a class.
///
/// The mirror image of [_reflectorClasses], and needed because that check is
/// one-directional. It reports a class the generated file is missing — but an
/// annotation that has come loose takes its class *out of the declared set*, so
/// nothing is missing and nothing is reported. The class simply stops being
/// discoverable, quietly, in both the source and the artifact.
///
/// That is not hypothetical. `MariaDbDatasource`'s `@tomReflector` and
/// `@TomDatasourceDriver('mariadb')` were separated from their class by two
/// private helpers written between them, so the `mariadb` driver left the
/// registry and every server configured for that type would have failed at
/// start-up with `no_driver_found`. Nothing said so: driver discovery is
/// exercised only by a `@Tags(['db'])` suite that skips itself without a
/// database.
///
/// Attribution is the same line-based run [_reflectorClasses] uses — anything
/// that is not a further annotation, a comment or a blank line ends it — so the
/// two agree by construction about what "attached" means. What differs is only
/// which side of the answer is reported.
Set<String> _looseClassAnnotations(String source) {
  final loose = <String>{};
  final pending = <String>[];
  var parenDepth = 0;

  for (final raw in const LineSplitter().convert(source)) {
    final line = raw.trim();

    if (parenDepth > 0) {
      parenDepth += _netParens(line);
      continue;
    }
    if (line.isEmpty || line.startsWith('//')) continue;

    if (line.startsWith('@')) {
      final name = RegExp(r'^@([A-Za-z_]\w*)').firstMatch(line)?.group(1);
      if (name != null && _classAnnotations.contains(name)) pending.add(name);
      parenDepth += _netParens(line);
      continue;
    }

    if (pending.isNotEmpty) {
      final onClass = RegExp(
        r'^(?:abstract\s+)?(?:base\s+|final\s+|interface\s+|sealed\s+)?'
        r'(?:class|mixin|enum)\s+\w+',
      ).hasMatch(line);
      if (!onClass) loose.addAll(pending.map((name) => '@$name -> $line'));
      pending.clear();
    }
  }
  return loose;
}

/// The annotations that make a **class** discoverable at runtime.
///
/// Each is read by a `tomReflector.annotatedClasses` walk somewhere in the
/// framework — services and components by the endpoint pipeline and the bean
/// locator, `TomDatasourceDriver` by datasource initialisation,
/// `TomScheduledJob` by the scheduler. One of these on anything but a class is
/// read by nobody.
///
/// `@TomEndpoint` is deliberately absent: it belongs on a *method*, so its
/// being on something other than a class is the normal case.
const Set<String> _classAnnotations = {
  'tomReflector',
  'tomService',
  'tomComponent',
  'TomDatasourceDriver',
  'TomApiImplementation',
  'TomScheduledJob',
};

/// Line-based for the same reason as [_reflectorClasses], and with one
/// difference that matters here: a field commonly carries `@TomEntityId()` or
/// `@TomAudited(...)` as well, in either order, so a pattern demanding the
/// declaration immediately after `@TomDbColumn` drops whichever fields happen
/// to be annotated the other way round. That failure is silent — the column
/// simply stops being checked — which is worse than a loud one.
Set<String> _columnFields(String source) {
  final found = <String>{};
  var pendingColumn = false;
  var parenDepth = 0;

  for (final raw in const LineSplitter().convert(source)) {
    final line = raw.trim();

    if (parenDepth > 0) {
      parenDepth += _netParens(line);
      continue;
    }
    if (line.isEmpty || line.startsWith('//')) continue;

    if (line.startsWith('@')) {
      if (line.startsWith('@TomDbColumn')) pendingColumn = true;
      parenDepth += _netParens(line);
      continue;
    }

    if (pendingColumn) {
      // A field declaration: `int? id;`, `String? title;`,
      // `TomZonedTime? remindAt;`, possibly with an initialiser.
      final field = RegExp(r'^[\w<>?,\s]+?\s(\w+)\s*[;=]').firstMatch(line);
      if (field != null) found.add(field.group(1)!);
    }
    pendingColumn = false;
  }
  return found;
}

String _read(String path) => File(p.normalize(path)).readAsStringSync();

void main() {
  group('a generated reflection file still describes its root', () {
    for (final root in _roots) {
      final generated = _read(root.generatedPath);
      final sources = _sourcesOf(root);

      test('${root.generatedPath} captures every reflected class', () {
        final declared = <String>{};
        for (final source in sources.values) {
          declared
            ..addAll(_reflectorClasses(source))
            ..addAll(_declaredExampleTypes(source));
        }
        declared.addAll(_declaredExampleTypes(_read(root.rootPath)));

        // The root must declare something, or the test passes by describing
        // nothing — the failure mode a name check is most prone to.
        expect(
          declared,
          isNotEmpty,
          reason:
              'No reflected class was found in ${sources.keys}. Either the '
              'sources moved or the annotation spelling changed; this test '
              'would then pass while checking nothing.',
        );

        final missing =
            declared.where((name) => !generated.contains("r'$name'")).toList()
              ..sort();

        expect(
          missing,
          isEmpty,
          reason:
              '${root.generatedPath} does not mention $missing.\n'
              'The checked-in reflection metadata is stale: these classes were '
              'added to the root since it was last generated. Run '
              './reflection_generation.sh (two to four minutes) and commit '
              'both generated files.',
        );
      });

      test('${root.generatedPath} captures every persisted column', () {
        final declared = <String>{};
        for (final source in sources.values) {
          declared.addAll(_columnFields(source));
        }

        expect(
          declared,
          isNotEmpty,
          reason:
              'No @TomDbColumn field was found in ${sources.keys}, so this '
              'test is checking nothing.',
        );

        final missing =
            declared.where((name) => !generated.contains(name)).toList()
              ..sort();

        expect(
          missing,
          isEmpty,
          reason:
              '${root.generatedPath} does not mention the column field(s) '
              '$missing.\n'
              'The entity reflects but the member does not, so the failure '
              'this prevents is a null column rather than a missing class. '
              'Run ./reflection_generation.sh and commit both generated files.',
        );
      });
    }
  });

  test('the fixture root is read against lib/, not the fixture alone', () {
    // Pins the scope by name. Narrowing `sourceDirectories` back to nothing
    // leaves every assertion above passing over the fixture's own dozen
    // classes, which is the state that let a detached `@tomReflector` in
    // `lib/` go unreported: the check ran, and `lib/` was not in it.
    final declared = <String>{};
    for (final source in _sourcesOf(_roots.first).values) {
      declared.addAll(_reflectorClasses(source));
    }
    expect(
      declared,
      containsAll(<String>['MariaDbDatasource', 'TomUserPreference']),
      reason: 'these are declared in lib/, not in the fixture',
    );
    expect(declared, hasLength(greaterThan(40)));
  });

  group('no class annotation has come loose from its class', () {
    for (final directory in const ['lib/src/tomserver', 'test/fixtures']) {
      test('in $directory', () {
        final loose = <String>[];
        var scanned = 0;
        for (final entry in Directory(directory).listSync(recursive: true)) {
          if (entry is! File ||
              !entry.path.endsWith('.dart') ||
              entry.path.endsWith('.reflection.dart')) {
            continue;
          }
          scanned++;
          for (final fault in _looseClassAnnotations(
            entry.readAsStringSync(),
          )) {
            loose.add('${entry.path}: $fault');
          }
        }
        expect(scanned, greaterThan(0), reason: 'nothing was read');
        expect(
          loose,
          isEmpty,
          reason:
              'a class annotation binds to whatever declaration follows it, so '
              'anything written in between silently moves it: '
              '${loose.join('; ')}. The class then leaves '
              '`tomReflector.annotatedClasses`, which is where every discovery '
              'walk in the framework looks — a start-up failure at a '
              'deployment, and nothing at all in a suite.',
        );
      });
    }

    test('the extractor reports a separated annotation', () {
      // Both directions, because a scanner that found nothing would pass the
      // two tests above while reading the same files.
      expect(
        _looseClassAnnotations('''
@tomReflector
@TomDatasourceDriver("mariadb")
String _helper(String s) => s;

class MariaDbDatasource {}
'''),
        {
          '@tomReflector -> String _helper(String s) => s;',
          '@TomDatasourceDriver -> String _helper(String s) => s;',
        },
      );
    });

    test('the extractor accepts what the package actually writes', () {
      // A wrapped argument list, a named-constructor annotation and a comment
      // between the run and the class all occur in `lib/`, and each is a shape
      // a stricter reading would report.
      expect(
        _looseClassAnnotations('''
@tomReflector
@TomDbTable(
  datasource: 'main',
  table: 'tom_thing',
)
// The grant rows are the row scope's own input.
@TomDbScope.unscoped()
abstract class TomThing {}
'''),
        isEmpty,
      );
    });
  });

  // The checks above are only as good as the two extractors feeding them: a
  // parser that silently stops recognising annotations makes every one of them
  // pass while checking nothing, and an over-eager one reports a stale file for
  // a class that was never meant to be captured. Both have happened here, so
  // both directions are pinned against a fixture whose shape is deliberate.
  group('the annotation extractors read the fixture as written', () {
    final fixture = _read('test/fixtures/reflection_fixture.dart');

    test('a @tomReflector class is attributed to its own declaration', () {
      expect(_reflectorClasses(fixture), contains('FixtureTaskRecord'));
    });

    test('an annotation does not reach across a class body', () {
      // `FixtureTaskRepository` follows `FixtureTaskRecord` and its doc comment
      // states in as many words that it carries no `@tomReflector`. An earlier
      // regex over the gap between annotation and declaration claimed it, and
      // reported the generated file stale for a class that is correctly absent.
      expect(
        _reflectorClasses(fixture),
        isNot(contains('FixtureTaskRepository')),
      );
    });

    test('a column is found whichever annotation is written first', () {
      // `@TomDbColumn` rarely stands alone: `@TomEntityId()` and
      // `@TomAudited(...)` sit beside it in either order. A pattern demanding
      // the field immediately after the column annotation drops whichever
      // fields are annotated the other way round — and drops them silently,
      // which is why the surviving count is asserted rather than eyeballed.
      final columns = _columnFields(fixture);
      expect(columns, contains('id'));
      expect(
        columns.length,
        greaterThan(10),
        reason:
            'Only ${columns.length} @TomDbColumn field(s) were recognised in '
            'the fixture. The extractor has stopped matching a common '
            'annotation layout, which weakens every column check silently.',
      );
    });
  });
}
